    payee_ok = False
    for value in inputs["covered_payee_categories"]:
        if inputs["payee_category"] == value:
            payee_ok = True
    timing_ok = False
    for value in inputs["covered_payment_timings"]:
        if inputs["payment_timing"] == value:
            timing_ok = True
    reason_ok = False
    for value in inputs["covered_termination_reasons"]:
        if inputs["termination_reason"] == value:
            reason_ok = True
