def apply(inputs, premises):
    weights = inputs["bag_weights"]
    dimensions = inputs["bag_dimensions"]
    n = len(weights)
    checked_weights = [0] * n
    checked_sizes = [0] * n
    checked_count = 0
    personal_used = 0
    carry_used = 0
    for i in range(n):
        a = dimensions[3 * i]
        b = dimensions[3 * i + 1]
        c = dimensions[3 * i + 2]
        fits_personal = a <= inputs["personal_item_limits"][0] and b <= inputs["personal_item_limits"][1] and c <= inputs["personal_item_limits"][2]
        fits_carry = a <= inputs["carry_on_limits"][0] and b <= inputs["carry_on_limits"][1] and c <= inputs["carry_on_limits"][2]
        cabin_item = False
        if fits_personal and personal_used < inputs["personal_item_count"]:
            personal_used = personal_used + 1
            cabin_item = True
        elif fits_carry and carry_used < inputs["carry_on_count"]:
            carry_used = carry_used + 1
            cabin_item = True
        if not cabin_item:
            checked_weights[checked_count] = weights[i]
            checked_sizes[checked_count] = a + b + c
            checked_count = checked_count + 1
    base_total = 0
    for i in range(checked_count):
        if i < len(inputs["checked_bag_fees"]):
            base_total = base_total + inputs["checked_bag_fees"][i]
        elif len(inputs["checked_bag_fees"]) > 0:
            base_total = base_total + inputs["checked_bag_fees"][len(inputs["checked_bag_fees"]) - 1]
    charged_excess = [0] * checked_count
    savings = [0] * checked_count
    for i in range(checked_count):
        size_fee = 0
        if checked_sizes[i] > inputs["standard_dimension_limit"]:
            size_fee = inputs["oversize_fees"][len(inputs["oversize_fees"]) - 1]
            for j in range(len(inputs["oversize_upper_bounds"])):
                if checked_sizes[i] <= inputs["oversize_upper_bounds"][j]:
                    size_fee = inputs["oversize_fees"][j]
                    break
        charged_weight_fee = 0
        if checked_weights[i] > inputs["charged_weight_limit"]:
            charged_weight_fee = inputs["overweight_fees"][len(inputs["overweight_fees"]) - 1]
            for j in range(len(inputs["overweight_upper_bounds"])):
                if checked_weights[i] <= inputs["overweight_upper_bounds"][j]:
                    charged_weight_fee = inputs["overweight_fees"][j]
                    break
        complimentary_weight_fee = 0
        if checked_weights[i] > inputs["complimentary_weight_limit"]:
            complimentary_weight_fee = inputs["overweight_fees"][len(inputs["overweight_fees"]) - 1]
            for j in range(len(inputs["overweight_upper_bounds"])):
                if checked_weights[i] <= inputs["overweight_upper_bounds"][j]:
                    complimentary_weight_fee = inputs["overweight_fees"][j]
                    break
        charged_fee = size_fee + charged_weight_fee
        complimentary_fee = size_fee + complimentary_weight_fee
        if inputs["use_higher_size_or_weight_fee"]:
            charged_fee = max(size_fee, charged_weight_fee)
            complimentary_fee = max(size_fee, complimentary_weight_fee)
        charged_excess[i] = charged_fee
        savings[i] = max(0, charged_fee - complimentary_fee)
    excess_total = sum(charged_excess)
    ordered_savings = sorted(savings)
    free_count = min(inputs["complimentary_bag_count"], checked_count)
    for i in range(free_count):
        excess_total = excess_total - ordered_savings[checked_count - 1 - i]
    answer = int(inputs["ticket_price"] + base_total + excess_total)
    return {"answer": answer}
